'use strict';
// Workspace interaction layer. Drafts always reference their owning document.
const studio={tagQuery:'',tagPage:0,panes:[],active:0,files:new Map(),settings:null,searchLimit:60};
function interfacePrefs(){return vault.interface??={sidebarHidden:innerWidth<=650,connectionsHidden:innerWidth<1150,collapsed:{}}}
function applyInterface(){const p=interfacePrefs();document.body.classList.toggle('sidebar-hidden',!!p.sidebarHidden);document.body.classList.toggle('connections-hidden',!!p.connectionsHidden);const toggle=$('[data-action="sidebar"]');toggle?.setAttribute('aria-expanded',String(!p.sidebarHidden));toggle?.setAttribute('title',p.sidebarHidden?'Fixar barra lateral':'Ocultar barra lateral');$('#sidebar-reveal')?.setAttribute('tabindex',p.sidebarHidden?'0':'-1')}
function saveInterface(){persist();applyInterface()}
actions.sidebar=()=>{interfacePrefs().sidebarHidden=!interfacePrefs().sidebarHidden;document.body.classList.remove('sidebar-peek');saveInterface()};
actions['toggle-connections']=()=>{interfacePrefs().connectionsHidden=!interfacePrefs().connectionsHidden;saveInterface();updateStudioTools()};
const reveal=document.createElement('button');reveal.id='sidebar-reveal';reveal.setAttribute('aria-label','Mostrar barra lateral temporariamente');reveal.title='Aproxime para revelar a barra lateral';document.body.append(reveal);
let peekTimer,sidebarPointer=null;
document.addEventListener('pointermove',e=>{sidebarPointer={x:e.clientX,y:e.clientY};if(interfacePrefs().sidebarHidden&&e.clientX<=16&&!$('#modal-root')?.children.length)showSidebarPeek()});
function showSidebarPeek(){clearTimeout(peekTimer);if(interfacePrefs().sidebarHidden&&!document.body.classList.contains('focus-mode'))document.body.classList.add('sidebar-peek')}
function hideSidebarPeek(){clearTimeout(peekTimer);peekTimer=setTimeout(()=>{const bounds=$('#sidebar').getBoundingClientRect();const inside=sidebarPointer&&sidebarPointer.x>=0&&sidebarPointer.x<=bounds.right&&sidebarPointer.y>=bounds.top&&sidebarPointer.y<=bounds.bottom;if(!inside)document.body.classList.remove('sidebar-peek')},220)}
reveal.onpointerenter=showSidebarPeek;reveal.onfocus=showSidebarPeek;reveal.onclick=showSidebarPeek;reveal.onpointerleave=hideSidebarPeek;
$('#sidebar').addEventListener('pointerenter',()=>clearTimeout(peekTimer));$('#sidebar').addEventListener('pointerleave',hideSidebarPeek);$('#sidebar').addEventListener('focusout',hideSidebarPeek);
document.addEventListener('pointerdown',e=>{if(!e.target.closest('#sidebar,#sidebar-reveal'))document.body.classList.remove('sidebar-peek')});

function collectionSection(id,title,body,count=''){const closed=!!interfacePrefs().collapsed?.[id];return `<section class="collection-group"><button class="collection-heading" data-collection-toggle="${id}" aria-expanded="${!closed}" aria-controls="collection-${id}">${icon('chevron')}<span>${title}</span><small>${count}</small></button><div id="collection-${id}" ${closed?'hidden':''}>${body}</div></section>`}
function renderTagList(){const page=AmagoEditing.tagPage(discoveryDocs(),studio.tagQuery,studio.tagPage);studio.tagPage=page.page;return `<div class="bounded-tags">${page.items.map(([tag,count])=>`<button class="tag-chip" data-collection-tag="${esc(tag)}"># ${esc(tag)}<small>${count}</small></button>`).join('')||'<p class="side-empty">Nenhuma tag encontrada.</p>'}</div><div class="tag-pagination"><span>${page.total} tags · ${page.page+1}/${page.pages}</span><button data-tag-page="-1" ${!page.page?'disabled':''} aria-label="Tags anteriores">←</button><button data-tag-page="1" ${page.page===page.pages-1?'disabled':''} aria-label="Próximas tags">→</button></div>`}
collectionPanel=function(){const project=workbench.source==='project',files=projectFiles();const quick=project?[['markdown','Markdown'],['text','Texto e código'],['image','Imagens'],['file','Outros arquivos']].map(([type,label])=>`<button class="collection-entry" data-project-kind="${type}">${icon(fileLabel(type))}${label}<small>${files.filter(f=>f.kind===type).length}</small></button>`).join(''):`<button class="collection-entry" data-view="all">${icon('note')}Todas as notas<small>${vault.notes.length}</small></button><button class="collection-entry" data-view="favorites">${icon('star')}Favoritos<small>${vault.notes.filter(n=>n.favorite).length}</small></button><button class="collection-entry" data-action="daily">${icon('calendar')}Nota do dia</button><button class="collection-entry" data-action="templates">${icon('layers')}Modelos</button><button class="collection-entry" data-action="trash">${icon('trash')}Lixeira<small>${vault.trash.length}</small></button>`;return collectionSection('quick',project?'ARQUIVOS POR TIPO':'ACESSO RÁPIDO',quick)+collectionSection('tags','TAGS',`<div class="side-search tag-query">${icon('search')}<input id="collection-tag-query" aria-label="Buscar tags da coleção" placeholder="Encontrar uma tag…" value="${esc(studio.tagQuery)}"></div><div id="collection-tag-results">${renderTagList()}</div>`)};
const studioTree=renderTree;
renderTree=function(){if(workbench.tab==='search')workbench.tab='explore';studioTree();const searchTab=$('[data-side-tab="search"]');searchTab?.setAttribute('aria-haspopup','dialog');searchTab?.removeAttribute('aria-selected');searchTab?.setAttribute('role','button');searchTab?.setAttribute('tabindex','0');$('#sidebar .brand')?.insertAdjacentHTML('afterend',`<button class="sidebar-pin icon-button" data-studio-pin aria-label="${interfacePrefs().sidebarHidden?'Fixar':'Ocultar'} barra lateral" title="${interfacePrefs().sidebarHidden?'Fixar':'Ocultar'} barra lateral">${icon('panel')}</button>`);$('#collection-tag-query')?.addEventListener('input',e=>{studio.tagQuery=e.target.value;studio.tagPage=0;$('#collection-tag-results').innerHTML=renderTagList()});applyInterface()};

function updateModalSearch(){const results=$('#hybrid-results');if(!results)return;const docs=discoveryDocs().filter(d=>(!workbench.filter||d.kind===workbench.filter)&&AmagoSearch.matches(d,workbench.query));$('#hybrid-count').textContent=`${docs.length} resultado${docs.length===1?'':'s'} · ${searchSummary()}`;$('#hybrid-chips').innerHTML=AmagoSearch.tokens(workbench.query).map((t,i)=>`<button class="query-chip" data-hybrid-remove="${i}" aria-label="Remover ${esc(t.raw)}">${esc(t.raw)} ×</button>`).join('');results.innerHTML=docs.slice(0,studio.searchLimit).map(d=>`<button class="hybrid-result" data-hybrid-open="${esc(docId(d))}">${icon(fileLabel(d.kind||'markdown'))}<span><strong>${esc(d.title||d.name)}</strong><small>${esc(d.path||d.folder)} · ${esc(AmagoSearch.documentData(d).tags.map(t=>'#'+t).join(' '))}</small><p>${esc((d.body||'').replace(/^---[\s\S]*?---\s*/,'').slice(0,170))}</p></span><span>↵</span></button>`).join('')||'<p class="no-results">Nenhum resultado. Remova um filtro para ampliar a busca.</p>';if(docs.length>studio.searchLimit)results.insertAdjacentHTML('beforeend',`<button class="plain-button load-search-results" data-hybrid-more>Mostrar mais resultados (${docs.length-studio.searchLimit})</button>`)}
search=actions.search=()=>{studio.settings=null;studio.searchLimit=60;modal('Buscar no workspace',`<div class="hybrid-modal-input">${icon('search')}<input id="hybrid-query" aria-label="Busca híbrida" placeholder="Nome, conteúdo, #tag, @menção, date:2026-11…" value="${esc(workbench.query)}"><kbd>Ctrl K</kbd></div><div id="hybrid-chips" class="query-chips"></div><details class="hybrid-refine"><summary>Refinar por tags, menções e datas</summary><form id="hybrid-refine-form"><label>Tag<input class="field" name="tag" placeholder="design"></label><label>Menção<input class="field" name="mention" placeholder="Pessoa ou nota"></label><label>De<input class="field" name="after" type="date"></label><label>Até<input class="field" name="before" type="date"></label><button class="plain-button">Aplicar</button></form></details><p id="hybrid-count" class="hybrid-count" aria-live="polite"></p><div id="hybrid-results"></div><div class="hybrid-modal-footer">${queryHelp()}<span>↑ ↓ navegar · Enter abrir · Esc fechar</span></div>`);$('.modal').classList.add('search-modal');$('#hybrid-query').oninput=e=>{workbench.query=e.target.value;studio.searchLimit=60;updateModalSearch()};$('#hybrid-refine-form').onsubmit=e=>{e.preventDefault();for(const [key,value] of new FormData(e.target))if(value)workbench.query+=' '+key+':"'+String(value).replaceAll('"','')+'"';workbench.query=workbench.query.trim();$('#hybrid-query').value=workbench.query;updateModalSearch()};updateModalSearch();if(workbench.source==='project'&&!discovery.docs.length)indexProject()};
const priorSearchRefresh=refreshSearchResults;refreshSearchResults=()=>{priorSearchRefresh();updateModalSearch();if($('#collection-tag-results'))$('#collection-tag-results').innerHTML=renderTagList()};

// Existing theme/plugin managers keep their event handlers inside the larger settings shell.
const studioModal=modal,studioClose=closeModal,settingsV22=actions.settings,themesV22=actions.themes,pluginsV22=actions.plugins;
const settingTabs=[['general','Geral','panel'],['appearance','Aparência','layers'],['data','Dados','folder'],['plugins','Plugins','core']];
function settingsShell(tab,content){studioModal('Configurações',`<div class="settings-layout"><nav class="settings-tabs" role="tablist" aria-label="Categorias de configurações">${settingTabs.map(([id,label,glyph])=>`<button role="tab" id="settings-${id}" aria-selected="${id===tab}" aria-controls="settings-content" tabindex="${id===tab?0:-1}" data-settings-tab="${id}">${icon(glyph)}${label}</button>`).join('')}</nav><section id="settings-content" class="settings-content" role="tabpanel" aria-labelledby="settings-${tab}">${content}</section></div>`);$('.modal').classList.add('settings-modal')}
modal=function(title,body){if(studio.settings==='appearance'&&title==='Aparência e temas')return settingsShell('appearance',body);if(studio.settings==='plugins'&&title==='Plugins e extensões')return settingsShell('plugins',body);studioModal(title,body)};
closeModal=function(){studio.settings=null;studioClose()};actions.close=closeModal;
function showSettings(tab='general'){
 studio.settings=tab;
 if(tab==='appearance'){studio.settings=null;settingsV22();const acrylic=$('.acrylic-controls');studio.settings='appearance';themesV22();if(acrylic)$('#settings-content').append(acrylic);return}
 if(tab==='plugins'){pluginsV22();return}
 if(tab==='data'){settingsShell(tab,`<div class="eyebrow">ARMAZENAMENTO LOCAL</div><h3>Seus dados, sob seu controle.</h3><p>${window.amagoDesktop?'A biblioteca pessoal é gravada no perfil do Windows, com uma cópia diária anterior em backups.':'A biblioteca pessoal é salva neste navegador. Exporte uma cópia antes de limpar os dados do site.'}</p><div class="settings-stat">${vault.notes.length} notas · ${vault.folders.length} pastas · ${vault.trash.length} notas na lixeira</div><div class="settings-button-grid"><button class="plain-button" data-action="backup">${icon('download')}Exportar espaço (.json)</button><button class="plain-button" data-action="import">${icon('upload')}Importar notas</button><button class="plain-button" data-action="trash">${icon('trash')}Abrir lixeira</button>${window.amagoDesktop?'<button class="plain-button" data-action="data-folder">Abrir pasta de dados</button>':''}</div><h3>Projetos de pasta</h3><p>Arquivos de texto são gravados na pasta original com Ctrl S. Alterações externas são verificadas antes de salvar. O backup da biblioteca não inclui arquivos de projetos.</p><p>Não há sincronização automática entre dispositivos.</p>`);return}
 const p=interfacePrefs();settingsShell(tab,`<div class="eyebrow">SEU ESPAÇO DE TRABALHO</div><h3>Navegação e edição</h3><label class="settings-option"><span><strong>Barra lateral recolhida</strong><small>Aproxime o mouse da borda esquerda para revelar. A preferência permanece após reiniciar.</small></span><input type="checkbox" id="setting-sidebar" ${p.sidebarHidden?'checked':''}></label><label class="settings-option"><span><strong>Mostrar conexões da nota</strong><small>O painel também pode ser alternado pelo botão Conexões, acima do editor.</small></span><input type="checkbox" id="setting-connections" ${!p.connectionsHidden?'checked':''}></label><label class="settings-option"><span><strong>Mostrar splash animada ao iniciar</strong><small>Desative para abrir diretamente o seletor de espaços. Vale para as próximas inicializações.</small></span><input type="checkbox" id="setting-splash" ${p.splashEnabled!==false?'checked':''}></label><div class="settings-shortcuts"><h3>Atalhos</h3><p><kbd>Ctrl K</kbd> Busca em modal</p><p><kbd>Ctrl Shift D</kbd> Adicionar nota lado a lado</p><p><kbd>Ctrl S</kbd> Salvar os arquivos abertos</p><p><kbd>Ctrl Shift P</kbd> Paleta de comandos</p></div>`);$('#setting-splash').onchange=e=>{p.splashEnabled=e.target.checked;window.amagoStartup.setEnabled(p.splashEnabled);saveInterface()};$('#setting-sidebar').onchange=e=>{p.sidebarHidden=e.target.checked;saveInterface()};$('#setting-connections').onchange=e=>{p.connectionsHidden=!e.target.checked;saveInterface();updateStudioTools()}}
actions.settings=()=>showSettings();actions.themes=()=>studio.settings?showSettings('appearance'):themesV22();actions.plugins=()=>studio.settings?showSettings('plugins'):pluginsV22();

function paneDocument(pane){if(!pane)return null;return pane.source==='vault'?vault.notes.find(n=>n.id===pane.id):studio.files.get(pane.id)}
function currentPane(){return workbench.source==='project'&&AmagoFiles.editable(workbench.file)?{source:'project',id:workbench.file.path,mode:'edit'}:workbench.source==='vault'?{source:'vault',id:state.id,mode:'edit'}:null}
function multiActive(){return studio.panes.length>1&&studio.panes[0].source===workbench.source&&((state.view==='notes'&&!state.tag)||(state.view==='project'&&AmagoFiles.editable(workbench.file)))}
function cacheCurrentFile(){const file=workbench.file;if(AmagoFiles.editable(file))studio.files.set(file.path,file)}
function activatePane(index){studio.active=index;const pane=studio.panes[index],doc=paneDocument(pane);if(!doc)return;if(pane.source==='vault'){state.id=pane.id;state.view='notes'}else{workbench.file=doc;state.view='project'}document.querySelectorAll('.editing-pane').forEach((el,i)=>el.classList.toggle('active',i===index));renderTabs();const context=$('#main>.context-panel');if(context)context.outerHTML=pane.source==='vault'?renderContext(doc):projectNoteContext();updateStudioTools();$('#crumb-folder').textContent=doc.path||doc.folder||doc.title;updatePaneStats()}
function updatePaneStats(){if(workbench.source==='vault'){updateStats();return}const doc=workbench.file;if(AmagoFiles.editable(doc)){$('#word-count').textContent=doc.body.trim().split(/\s+/).filter(Boolean).length+' palavras';$('#reading-time').textContent='Pasta local'}}
function paneStatus(doc){return doc.error||doc.conflict?'Conflito ou erro ao salvar':doc.saving?'Salvando…':doc.dirty?'Alterações não salvas':'Salvo'}
function renderPaneStatus(){document.querySelectorAll('[data-pane-status]').forEach(el=>{const doc=paneDocument(studio.panes[+el.dataset.paneStatus]);if(doc)el.textContent=paneStatus(doc)});document.querySelectorAll('[data-pane-warning]').forEach(el=>{const pane=studio.panes[+el.dataset.paneWarning],doc=paneDocument(pane);el.innerHTML=doc?.error||doc?.conflict?`<div class="pane-conflict"><strong>${esc(doc.error||'O arquivo mudou no disco.')}</strong><span>Seu rascunho foi preservado.</span><button class="plain-button" data-pane-export="${el.dataset.paneWarning}">Exportar rascunho</button><button class="plain-button" data-pane-reload="${el.dataset.paneWarning}">Recarregar do disco</button></div>`:''})}
function renderSplitEditors(){const valid=studio.panes.filter(p=>paneDocument(p));studio.panes=valid;if(valid.length<2)return false;studio.active=Math.min(studio.active,valid.length-1);$('#main').innerHTML=`<section class="split-workspace"><header class="split-workspace-heading"><span>${icon('panel')}Notas lado a lado <small>${valid.length} colunas</small></span><div><button class="plain-button" data-action="split-note">${icon('plus')}Adicionar nota</button><button class="plain-button" data-studio-single>Uma coluna</button></div></header><div class="editing-columns" style="--pane-count:${valid.length}">${valid.map((pane,index)=>{const doc=paneDocument(pane);return `<section class="editing-pane ${index===studio.active?'active':''}" data-pane="${index}"><header><button class="pane-title" data-pane-choose="${index}" title="Trocar nota nesta coluna">${icon('note')}<span>${esc(doc.title||doc.name)}</span>${icon('chevron')}</button><button class="icon-button" data-pane-properties="${index}" aria-label="Propriedades de ${esc(doc.title||doc.name)}" title="Propriedades">${icon('settings')}</button><button class="icon-button" data-pane-mode="${index}" aria-label="${pane.mode==='read'?'Editar':'Prévia de'} ${esc(doc.title||doc.name)}" title="Alternar edição e prévia">${icon(pane.mode==='read'?'edit':'eye')}</button><button class="icon-button" data-pane-close="${index}" aria-label="Fechar coluna ${index+1}" title="Fechar coluna">${icon('close')}</button></header><div data-pane-warning="${index}"></div>${pane.mode==='read'?`<article class="markdown pane-preview">${pane.source==='vault'?markdown(doc.body,false,doc):doc.kind==='text'?'<pre>'+esc(doc.body)+'</pre>':fileMarkdown(doc.body,doc)}</article>`:`<textarea data-pane-editor="${index}" aria-label="Editar ${esc(doc.title||doc.name)} na coluna ${index+1}" spellcheck="false">${esc(doc.body)}</textarea>`}<footer><span>${pane.source==='project'?esc(doc.path):esc(doc.folder)}</span><span data-pane-status="${index}">${pane.source==='project'?paneStatus(doc):'Salvamento automático'}</span></footer></section>`}).join('')}</div></section>${workbench.source==='vault'?renderContext(note()):''}`;
 document.querySelectorAll('[data-pane-editor]').forEach(editor=>{const pane=studio.panes[+editor.dataset.paneEditor],doc=paneDocument(pane);editor.oninput=()=>{doc.body=editor.value;if(pane.source==='vault'){doc.updated=stamp();clearTimeout(saveTimer);saveTimer=setTimeout(persist,350)}else doc.dirty=doc.body!==doc.savedBody;renderPaneStatus();updatePaneStats()};editor.onkeydown=e=>{if(e.key==='Tab'){e.preventDefault();editor.setRangeText('  ',editor.selectionStart,editor.selectionEnd,'end');editor.dispatchEvent(new Event('input'))}}});
 document.querySelectorAll('.editing-pane').forEach(el=>el.addEventListener('focusin',()=>{if(studio.active!==+el.dataset.pane)activatePane(+el.dataset.pane)}));renderPaneStatus();updatePaneStats();return true;
}
function choosePane(replace=null){const first=currentPane();if(!first){toast('Abra um Markdown para dividir o editor.');return}cacheCurrentFile();if(replace===null&&!multiActive()){studio.panes=[first];studio.active=0}const docs=workbench.source==='project'?projectFiles().filter(d=>AmagoFiles.editable(d)):vault.notes;if(replace===null&&studio.panes.length>=4){toast('Até quatro colunas por workspace. Feche uma coluna para adicionar outra.');return}modal(replace===null?'Abrir nota lado a lado':'Trocar nota da coluna',`<input class="field" id="pane-picker-query" placeholder="Encontrar uma nota…" aria-label="Encontrar nota para a coluna"><div id="pane-picker-results" class="pane-picker-results"></div>`);const update=()=>{const query=AmagoSearch.normalize($('#pane-picker-query').value);$('#pane-picker-results').innerHTML=docs.filter(d=>AmagoSearch.normalize(d.title||d.path).includes(query)).map(d=>`<button class="search-result" data-pane-pick="${esc(docId(d))}" data-pane-replace="${replace===null?'add':replace}">${icon('note')}<span><strong>${esc(d.title||d.name)}</strong><small>${esc(d.path||d.folder)}</small></span></button>`).join('')||'<p class="side-empty">Nenhuma nota encontrada.</p>'};$('#pane-picker-query').oninput=update;update()}
actions['split-note']=()=>choosePane();commandList.push(['Abrir nota lado a lado','split-note','Ctrl Shift D']);
async function putPane(id,replace){const source=workbench.source,current=currentPane();if(!current)return;cacheCurrentFile();if(!studio.panes.length||studio.panes[0].source!==source)studio.panes=[current];const existing=studio.panes.findIndex(p=>p.id===id);if(existing>=0){studio.active=existing;closeModal();renderMain();activatePane(existing);return}if(source==='project'&&!studio.files.get(id)?.dirty){const result=await window.projectAdapter.read(id);if(result.error){toast(result.error);return}studio.files.set(id,{...projectFiles().find(f=>f.path===id),...result,savedBody:result.body,dirty:false})}const pane={source,id,mode:'edit'};if(replace==='add'){studio.panes.push(pane);studio.active=studio.panes.length-1}else{studio.active=+replace;studio.panes[studio.active]=pane}closeModal();if(source==='vault'){state.id=id;state.view='notes';if(!state.tabs.includes(id))state.tabs.push(id)}else{workbench.file=studio.files.get(id);state.view='project';if(!workbench.tabs.includes(id))workbench.tabs.push(id)}state.tag=null;render();activatePane(studio.active)}
saveProjectFile=async function(){cacheCurrentFile();let success=true;for(const file of new Set([...studio.files.values(),workbench.file].filter(f=>AmagoFiles.editable(f)))){const result=await AmagoEditing.saveDraft(file,window.projectAdapter);if(result.error||result.conflict){success=false;toast(file.name+': '+(result.error||'O arquivo mudou no disco. Rascunho preservado.'))}else{const indexed=discovery.docs.find(d=>d.path===file.path);if(indexed)Object.assign(indexed,{body:file.body,version:file.version})}}renderPaneStatus();if(workbench.file?.conflict&&$('#project-message'))renderProjectBanner();markFileStatus(success?'Arquivos salvos':'Há arquivos não salvos');return success};workActions.save=saveProjectFile;
const studioOpenNote=openNote,studioOpenProjectFile=openProjectFile,studioOpenProject=openProject;
openNote=function(id){if(studio.panes.length>1&&studio.panes[0].source==='vault'&&workbench.source==='vault'&&vault.notes.some(n=>n.id===id)){const existing=studio.panes.findIndex(p=>p.id===id);if(existing>=0)studio.active=existing;else studio.panes[studio.active]={source:'vault',id,mode:'edit'};state.id=id;state.view='notes';state.tag=null;if(!state.tabs.includes(id))state.tabs.push(id);render();return}return studioOpenNote(id)};
openProjectFile=async function(path){cacheCurrentFile();const splitting=studio.panes.length>1&&studio.panes[0].source==='project'&&workbench.source==='project';await studioOpenProjectFile(path);if(workbench.file?.path!==path)return;cacheCurrentFile();if(splitting&&AmagoFiles.editable(workbench.file)){const existing=studio.panes.findIndex(p=>p.id===path);if(existing>=0)studio.active=existing;else studio.panes[studio.active]={source:'project',id:path,mode:'edit'};renderMain()}};
openProject=async(...args)=>{const before=workbench.project;await studioOpenProject(...args);if(before!==workbench.project){studio.files.clear();studio.panes=[];studio.active=0}};workActions.open=openProject;actions['open-project']=openProject;
function activeProperties(){const pane=multiActive()?studio.panes[studio.active]:currentPane(),doc=pane&&paneDocument(pane)|| (workbench.source==='project'?workbench.file:note());if(!doc)return;const project=workbench.source==='project',color=AmagoSearch.metadata(doc.body).color||'#78e2df';modal(project?'Propriedades do Markdown':'Propriedades da nota',`<form id="studio-properties"><div class="property-file">${icon('note')}<span>${esc(doc.path||doc.title)}</span></div>${!project?`<label>Pasta<select class="field" id="studio-prop-folder">${vault.folders.map(f=>`<option ${doc.folder===f?'selected':''}>${esc(f)}</option>`).join('')}</select></label><label>Tags separadas por vírgula<input class="field" id="studio-prop-tags" value="${esc(doc.tags.join(', '))}"></label>`:''}<label for="studio-prop-color">Cor do ponto no mapa</label><div class="property-color"><input id="studio-prop-color" type="color" value="${color}" aria-label="Cor do ponto no mapa"><input class="field" id="studio-prop-hex" value="${color}" aria-label="Cor hexadecimal" pattern="#[0-9a-fA-F]{6}" required maxlength="7"></div><p>A cor é gravada na propriedade <code>color</code> do Markdown e acompanha a nota ao exportar.</p><div class="modal-actions">${!project?'<button type="button" class="plain-button" data-action="export-note">Exportar Markdown</button><button type="button" class="plain-button" data-action="delete-note">Mover para a lixeira</button>':''}<button class="solid-button">Salvar propriedades</button></div></form>`);$('#studio-prop-color').oninput=e=>$('#studio-prop-hex').value=e.target.value;$('#studio-prop-hex').oninput=e=>{if(/^#[\da-f]{6}$/i.test(e.target.value))$('#studio-prop-color').value=e.target.value};$('#studio-properties').onsubmit=async e=>{e.preventDefault();const color=$('#studio-prop-hex').value;if(!/^#[\da-f]{6}$/i.test(color))return;doc.body=AmagoSearch.withColor(doc.body,color);if(project){doc.dirty=doc.body!==doc.savedBody;studio.files.set(doc.path,doc);if(!(await saveProjectFile()))return}else{doc.folder=$('#studio-prop-folder').value;doc.tags=[...new Set($('#studio-prop-tags').value.split(',').map(t=>t.trim().replace(/^#/,'' )).filter(Boolean))];doc.updated=stamp();persist()}closeModal();render()}}
actions['note-menu']=activeProperties;actions['project-properties']=activeProperties;
function updateStudioTools(){const editing=(state.view==='notes'&&!state.tag)||(state.view==='project'&&AmagoFiles.editable(workbench.file));let tools=$('#studio-tools');if(!tools){tools=document.createElement('div');tools.id='studio-tools';$('.header-right').prepend(tools)}tools.hidden=!editing;tools.innerHTML=`<button class="plain-button" data-action="split-note" title="Abrir nota lado a lado — Ctrl Shift D">${icon('panel')}<span>Dividir</span></button><button class="plain-button" data-action="toggle-connections" aria-pressed="${!interfacePrefs().connectionsHidden}" title="${interfacePrefs().connectionsHidden?'Mostrar':'Ocultar'} conexões">${icon('graph')}<span>Conexões</span></button>`;document.querySelectorAll('.context-panel').forEach(panel=>{const title=panel.querySelector('.context-title');if(!title)return;if(!title.querySelector('[data-action="toggle-connections"]'))title.insertAdjacentHTML('beforeend',`<button class="icon-button" data-action="toggle-connections" aria-label="Ocultar painel de conexões" title="Ocultar painel">${icon('close')}</button>`)});if(state.view==='project'&&AmagoFiles.editable(workbench.file)&&!multiActive()&&!$('[data-action="project-properties"]'))$('.project-document-toolbar>div:last-child')?.insertAdjacentHTML('beforeend',`<button class="icon-button" data-action="project-properties" aria-label="Propriedades do Markdown" title="Propriedades do Markdown">${icon('settings')}</button>`)}
const studioMain=renderMain;
renderMain=function(){if(!multiActive()||!renderSplitEditors())studioMain();if(state.view==='project'&&workbench.file?.kind==='markdown'&&!$('#main>.context-panel'))$('#main').insertAdjacentHTML('beforeend',projectNoteContext());updateStudioTools();applyInterface()};
const studioRender=render;render=function(){studioRender();applyInterface()};

document.addEventListener('click',async e=>{const el=e.target.closest('[data-collection-toggle],[data-tag-page],[data-collection-tag],[data-settings-tab],[data-studio-pin],[data-hybrid-open],[data-hybrid-remove],[data-hybrid-more],[data-pane-pick],[data-pane-choose],[data-pane-close],[data-pane-properties],[data-pane-mode],[data-pane-export],[data-pane-reload],[data-studio-single]');if(!el)return;e.preventDefault();e.stopImmediatePropagation();try{
 if(el.hasAttribute('data-studio-pin'))actions.sidebar();
 if(el.dataset.collectionToggle){const p=interfacePrefs();p.collapsed??={};p.collapsed[el.dataset.collectionToggle]=!p.collapsed[el.dataset.collectionToggle];persist();renderTree()}
 if(el.dataset.tagPage){studio.tagPage+=+el.dataset.tagPage;$('#collection-tag-results').innerHTML=renderTagList()}
 if(el.dataset.collectionTag){workbench.query='tag:"'+el.dataset.collectionTag.replaceAll('"','')+'"';workbench.filter=null;search()}
 if(el.dataset.settingsTab)showSettings(el.dataset.settingsTab);
 if(el.dataset.hybridOpen){const id=el.dataset.hybridOpen;closeModal();workbench.source==='project'?await openProjectFile(id):openNote(id)}
 if(el.dataset.hybridRemove!==undefined){workbench.query=AmagoSearch.tokens(workbench.query).filter((_,i)=>i!==+el.dataset.hybridRemove).map(t=>t.raw).join(' ');$('#hybrid-query').value=workbench.query;updateModalSearch()}
 if(el.hasAttribute('data-hybrid-more')){studio.searchLimit+=60;updateModalSearch()}
 if(el.dataset.panePick)await putPane(el.dataset.panePick,el.dataset.paneReplace);
 if(el.dataset.paneChoose!==undefined)choosePane(+el.dataset.paneChoose);
 if(el.dataset.paneProperties!==undefined){activatePane(+el.dataset.paneProperties);activeProperties()}
 if(el.dataset.paneMode!==undefined){const p=studio.panes[+el.dataset.paneMode];p.mode=p.mode==='read'?'edit':'read';renderMain()}
 if(el.dataset.paneClose!==undefined){if(!(await saveProjectFile()))return;studio.panes.splice(+el.dataset.paneClose,1);studio.active=Math.min(studio.active,studio.panes.length-1);if(studio.panes.length){const p=studio.panes[studio.active];if(p.source==='vault')state.id=p.id;else workbench.file=paneDocument(p)}render()}
 if(el.hasAttribute('data-studio-single')){if(!(await saveProjectFile()))return;studio.panes=[];studio.active=0;render()}
 if(el.dataset.paneExport!==undefined){const doc=paneDocument(studio.panes[+el.dataset.paneExport]);download((doc.name||doc.title)+'-rascunho.md',doc.body,'text/markdown;charset=utf-8')}
 if(el.dataset.paneReload!==undefined){const doc=paneDocument(studio.panes[+el.dataset.paneReload]);modal('Recarregar o arquivo?',`<p>O rascunho desta coluna será substituído. Exporte-o primeiro se quiser preservá-lo.</p><button class="solid-button" id="studio-confirm-reload">Recarregar do disco</button>`);$('#studio-confirm-reload').onclick=async()=>{const result=await window.projectAdapter.read(doc.path);if(result.error){toast(result.error);return}Object.assign(doc,result,{savedBody:result.body,dirty:false,conflict:false,error:null});closeModal();renderMain()}}
 }catch(error){toast(error.message)}},true);
window.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();e.stopImmediatePropagation();search();return}if((e.ctrlKey||e.metaKey)&&e.shiftKey&&e.key.toLowerCase()==='d'){e.preventDefault();e.stopImmediatePropagation();choosePane();return}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'&&multiActive()){e.preventDefault();e.stopImmediatePropagation();saveProjectFile();persist();return}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='e'&&multiActive()){e.preventDefault();e.stopImmediatePropagation();const p=studio.panes[studio.active];p.mode=p.mode==='read'?'edit':'read';renderMain();return}if($('#hybrid-query')&&['ArrowDown','ArrowUp','Enter'].includes(e.key)&&!e.target.closest('#hybrid-refine-form')){const results=[...document.querySelectorAll('[data-hybrid-open]')],index=results.indexOf(document.activeElement);if(e.key==='Enter'){if(e.target.id==='hybrid-query'){e.preventDefault();results[0]?.click()}}else{e.preventDefault();results[Math.max(0,Math.min(results.length-1,index+(e.key==='ArrowDown'?1:-1)))]?.focus()}}if(e.target.matches('[data-settings-tab]')&&['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const ids=settingTabs.map(t=>t[0]),i=ids.indexOf(studio.settings),next=e.key==='Home'?0:e.key==='End'?ids.length-1:(i+(e.key==='ArrowDown'?1:ids.length-1))%ids.length;showSettings(ids[next]);$('#settings-'+ids[next]).focus()}},true);
window.addEventListener('beforeunload',e=>{if(!window.amagoDesktop&&[...studio.files.values()].some(f=>f.dirty)){e.preventDefault();e.returnValue=''}});
window.addEventListener('amago-ready',()=>{applyInterface();renderTree();updateStudioTools()});
renderTree();updateStudioTools();applyInterface();

function projectNoteContext(){const f=workbench.file,docs=discoveryDocs().filter(d=>d.kind==='markdown'),linked=[...new Map(AmagoSearch.metadata(f.body).links.map(link=>resolveLink(docs,f,link)).filter(Boolean).map(d=>[d.path,d])).values()],back=docs.filter(d=>d.path!==f.path&&AmagoSearch.metadata(d.body).links.some(link=>resolveLink(docs,d,link)?.path===f.path));const list=items=>items.map(d=>'<button class="backlink" data-project-file="'+esc(d.path)+'">'+icon('note')+esc(d.title||d.name)+'</button>').join('')||'<p class="empty-small">Nenhuma conexão encontrada.</p>';return '<aside class="context-panel studio-project-context"><h3 class="context-title">'+icon('graph')+'Conexões da nota</h3><section class="panel-section"><h3 class="context-title">Links nesta nota</h3>'+list(linked)+'</section><section class="panel-section"><h3 class="context-title">Links para esta nota</h3>'+list(back)+'</section><button class="plain-button" data-open-universe>Abrir mapa do projeto</button></aside>'}
